import React, { useEffect, useRef } from 'react';
import * as THREE from 'three';
import { GLTFLoader } from 'three/examples/jsm/loaders/GLTFLoader';

const RobotScene = () => {
    const mountRef = useRef(null);

    useEffect(() => {
        const width = window.innerWidth;
        const height = window.innerHeight;

        const scene = new THREE.Scene();

        const camera = new THREE.PerspectiveCamera(50, width / height, 0.1, 100);
        camera.position.set(0, 1.5, 4);

        const renderer = new THREE.WebGLRenderer({ antialias: true, alpha: true });
        renderer.setSize(width, height);
        renderer.toneMapping = THREE.ACESFilmicToneMapping;
        
        const currentRef = mountRef.current;
        if (currentRef) {
            currentRef.appendChild(renderer.domElement);
        }

        const ambientLight = new THREE.AmbientLight(0xffffff, 0.5);
        scene.add(ambientLight);
        const mainLight = new THREE.DirectionalLight(0xffffff, 2);
        mainLight.position.set(2, 5, 5);
        scene.add(mainLight);

        let mixer;
        let headObject;
        const mouse = new THREE.Vector2();
        const windowHalf = new THREE.Vector2(window.innerWidth / 2, window.innerHeight / 2);

        const loader = new GLTFLoader();
        loader.load('/Samurai.glb', (gltf) => {
            const model = gltf.scene;
            scene.add(model);

            const torso = model.getObjectByName('Torso');
            const head = model.getObjectByName('Head');

            if (torso && head) {
                torso.attach(head);
                headObject = head;
            } else {
                console.log("Struktura modelu:", model);
            }

            if (gltf.animations.length > 0) {
                mixer = new THREE.AnimationMixer(model);
                mixer.clipAction(gltf.animations[0]).play();
            }
        });

        const handleMouseMove = (event) => {
            mouse.x = (event.clientX - windowHalf.x) / windowHalf.x;
            mouse.y = (event.clientY - windowHalf.y) / windowHalf.y;
        };
        document.addEventListener('mousemove', handleMouseMove);

        const clock = new THREE.Clock();
        let animationId;

        const animate = () => {
            animationId = requestAnimationFrame(animate);
            const delta = clock.getDelta();

            if (mixer) mixer.update(delta);

            if (headObject) {
                const limit = 0.8;
                const targetX = -mouse.y * limit;
                const targetY = -mouse.x * limit;
                headObject.rotation.x += (targetX - headObject.rotation.x) * 0.1;
                headObject.rotation.y += (targetY - headObject.rotation.y) * 0.1;
            }

            renderer.render(scene, camera);
        };
        animate();

        const handleResize = () => {
            windowHalf.set(window.innerWidth / 2, window.innerHeight / 2);
            camera.aspect = window.innerWidth / window.innerHeight;
            camera.updateProjectionMatrix();
            renderer.setSize(window.innerWidth, window.innerHeight);
        };
        window.addEventListener('resize', handleResize);

        return () => {
            document.removeEventListener('mousemove', handleMouseMove);
            window.removeEventListener('resize', handleResize);
            cancelAnimationFrame(animationId);
            if (currentRef) currentRef.removeChild(renderer.domElement);
            renderer.dispose();
        };
    }, []);

    return (
        <div 
            ref={mountRef} 
            style={{ 
                width: '100%', 
                height: '100vh', 
                pointerEvents: 'none' 
            }} 
        />
    );
};

export default RobotScene;
